// Test tab data: a recording of the real CleanGuard AI (ai/worker.py's
// model + rules) run on 5 simulated restrooms, generated by
// ai/build_test_replay.py. It is played back in real time -- one step every
// 15 seconds (sped up by TEST_SPEED below) -- so the Test tab works with
// no backend, database or Python running. Playback starts when the page
// loads (reload = start again) and loops at the end of the recording.

import replay from "../data/test_replay.json";

// Playback speed: 1 = real time (one step every 15 s). 5 = one step every
// 3 s, so the leak shows up after ~1 min instead of ~6 and the 45-minute
// recording loops every 9 minutes.
export const TEST_SPEED = 5;
const REAL_STEP_MS = replay.step_seconds * 1000;
const STEP_MS = REAL_STEP_MS / TEST_SPEED;
const STARTED_AT = Date.now();

function pad(n) {
  return String(n).padStart(2, "0");
}

// "YYYY-MM-DD HH:MM:SS" in the browser's local time, like the backend.
function stamp(ms) {
  const d = new Date(ms);
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())} ` +
    `${pad(d.getHours())}:${pad(d.getMinutes())}:${pad(d.getSeconds())}`;
}

function position() {
  const elapsed = Math.floor((Date.now() - STARTED_AT) / STEP_MS);
  const length = replay.devices[0].steps.length;
  const index = elapsed % length;
  // time of the current step, aligned to the 15 s grid since page load
  const at = STARTED_AT + elapsed * STEP_MS;
  return { index, at };
}

function findDevice(id) {
  return replay.devices.find((d) => d.id === id);
}

export function isTestDevice(id) {
  return Boolean(findDevice(id));
}

// Same shape as getSensors.php rows (including the latest AI decision).
export function getTestSensors() {
  const { index, at } = position();
  const created = stamp(at);
  return replay.devices.map((d) => {
    const step = d.steps[index];
    return {
      id: d.id,
      NAME: d.NAME,
      location: d.location,
      STATUS: "정상",
      temperature: step.t.toFixed(2),
      humidity: step.h.toFixed(2),
      air_quality: String(step.a),
      created_at: created,
      source: "test",
      ai_level: step.ai.level,
      ai_headline: step.ai.headline,
      ai_at: created,
    };
  });
}

// Same shape as getAIStatus.php.
export function getTestAIStatus(id) {
  const d = findDevice(id);
  if (!d) return { available: false };
  const { index, at } = position();
  return {
    ...d.steps[index].ai,
    available: true,
    source: "test",
    device_id: id,
    created_at: stamp(at),
  };
}

// Same shape as getHistory.php: 5-minute averages, oldest first --
// 3 h of recorded history followed by what has been played so far.
export function getTestHistory(id) {
  const d = findDevice(id);
  if (!d) return [];
  const { index, at } = position();
  const BUCKET = 20; // 20 steps x 15 s = 5 min
  const played = d.steps.slice(0, index + 1);
  const liveBuckets = [];
  for (let i = 0; i < played.length; i += BUCKET) {
    const chunk = played.slice(i, i + BUCKET);
    const mean = (key) => chunk.reduce((sum, s) => sum + s[key], 0) / chunk.length;
    liveBuckets.push([mean("t"), mean("h"), mean("a")]);
  }
  const all = [...d.history, ...liveBuckets];
  const end = at - (index % BUCKET) * REAL_STEP_MS;
  return all.map(([temperature, humidity, air], i) => ({
    created_at: stamp(end - (all.length - 1 - i) * BUCKET * REAL_STEP_MS),
    temperature: temperature.toFixed(2),
    humidity: humidity.toFixed(2),
    air_quality: air.toFixed(2),
  }));
}
